"""Controlled timing evidence, generated by the real entry assessor.

These synthetic clocks/path facts never authenticate the exported market data.
"""
from datetime import datetime, date, timedelta
from dataclasses import asdict
from types import SimpleNamespace

from app.modules.market_universe.market_universe_schemas import DisplayQuoteRead
from app.modules.stock_details.decision.entry_applicability import EntryPathFacts, evaluate_entry_applicability


def controlled_entry_transitions(universe, *, simulation_now=None):
    row = next((row for row in universe.rows if row.stock.symbol == "BSRMSTEEL" and row.decision.display_action == "POTENTIAL_BUY"), None)
    if row is None:
        return {"evidence_class": "CONTROLLED", "available": False, "reason": "NO_PERMITTED_EXPORTED_BSRMSTEEL_PLAN"}
    plan = row.analysis.trade_plan
    first = date(2026, 11, 15)
    now = datetime.fromisoformat("2026-11-15T05:00:00+00:00")
    opened = now.replace(hour=4)
    closed = now.replace(hour=9)
    price = (plan.entry_zone_low + plan.entry_zone_high) / 2
    quote = DisplayQuoteRead(current_price=price, as_of_trade_date=first.isoformat(), observation_session_date=first.isoformat(),
        observation_status="PROVISIONAL", data_quality="OK", volume=1000, source_observed_at=now, batch_fetched_at=now,
        session_date_verified=True)
    path = EntryPathFacts(sessions=(first,), complete=True)
    common = dict(decision=row.decision.canonical, plan=plan, eligibility=row.eligibility, reference_date=date(2026,11,12),
        now=now, market_open=True, coverage_verified=True, path=path, quote=quote, publication_observed_at=now-timedelta(days=2),
        session_open_at=opened, session_close_at=closed, price_basis_v2=True)
    cases = {}
    variants = {"fresh_current": {},
        "recent_fetch_only": {"quote": quote.model_copy(update={"source_observed_at": None})},
        "stale_trade": {"quote": quote.model_copy(update={"source_observed_at": now-timedelta(hours=2)})},
        "delayed_fetch": {"quote": quote.model_copy(update={"source_observed_at": now-timedelta(hours=2), "batch_fetched_at": now})},
        "no_trade": {"quote": quote.model_copy(update={"volume": 0})},
        "finalization_gap": {"market_open": False, "session_settling": True},
        "published_breach_recovered": {"path": EntryPathFacts(sessions=(first,), complete=True, reliable_lows=((first, plan.stop_loss),))},
        "provisional_coverage_unknown": {"path": EntryPathFacts(sessions=(first,), complete=False)},
        "withdrawn_publication": {"withdrawn": True},
        "next_open_expired": {"now": now+timedelta(days=15), "path": EntryPathFacts(sessions=tuple(date.fromisoformat(day) for day in
            ("2026-11-15","2026-11-16","2026-11-17","2026-11-18","2026-11-19","2026-11-22","2026-11-23","2026-11-24","2026-11-25","2026-11-26","2026-11-29")[:plan.expiry_sessions+1]), complete=True)},
    }
    finalized = quote.model_copy(update={"observation_status": "FINALIZED", "source_observed_at": closed, "batch_fetched_at": closed})
    next_open = opened+timedelta(days=1)
    variants["authenticated_last_close"] = {"now": next_open-timedelta(hours=1), "quote": finalized,
        "market_open": False, "session_close_at": closed, "finalized_session_date": first, "recheck_at": next_open}
    variants["closed_hours_last_close"] = {"now": closed+timedelta(hours=4), "quote": finalized,
        "market_open": False, "session_close_at": closed, "finalized_session_date": first, "recheck_at": next_open}
    variants["next_open_without_new_quote"] = {"now": next_open, "quote": finalized,
        "session_open_at": next_open, "session_close_at": closed+timedelta(days=1),
        "path": EntryPathFacts(sessions=(first,first+timedelta(days=1)), complete=True)}
    if simulation_now is not None:
        if simulation_now.tzinfo is None:
            raise ValueError("Controlled browser clock must include a timezone")
        # Explicit recorded Thursday-close reference through Sunday's open.
        # The source stock/plan stays genuine; all quote/path facts are CONTROLLED.
        close_day = date(2026,11,12)
        control_close = datetime.fromisoformat("2026-11-12T09:00:00+00:00")
        control_open = datetime.fromisoformat("2026-11-15T04:00:00+00:00")
        saved = finalized.model_copy(update={"as_of_trade_date": close_day.isoformat(), "observation_session_date": close_day.isoformat(),
            "source_observed_at": control_close, "batch_fetched_at": control_close})
        if not control_close <= simulation_now < control_open:
            raise ValueError("This dated controlled close fixture requires a clock between Nov12 close and Nov15 open")
        for key in ("authenticated_last_close", "closed_hours_last_close"):
            variants[key] = {"now": simulation_now, "quote": saved, "market_open": False, "session_close_at": control_close,
                "finalized_session_date": close_day, "recheck_at": control_open, "path": EntryPathFacts(complete=True)}
        variants["last_close_with_open_freshness"] = {**variants["authenticated_last_close"], "client_market_open": True}
    for cadence in (10,15):
        for key, updates in variants.items():
            args = {**common, **updates}
            client_open = args.pop("client_market_open", None)
            args["quote"] = args["quote"].model_copy(update={"max_age_seconds": cadence*120})
            result = evaluate_entry_applicability(**args)
            from app.core.audit_hashing import canonicalize_audit_value
            context = canonicalize_audit_value({key: args.get(key) for key in (
                "reference_date", "publication_observed_at", "market_open", "coverage_verified", "withdrawn",
                "session_open_at", "session_close_at", "recheck_at", "finalized_session_date", "session_settling", "price_basis_v2")})
            context["path"] = canonicalize_audit_value(asdict(args["path"]))
            context["next_session_close_at"] = (args["recheck_at"]+(closed-opened)).isoformat() if args.get("recheck_at") else None
            context["basis_coverage"]={"status":"CONTROLLED_PATH_BASIS_FACTS","complete":args["path"].complete,
                "known_at":args["now"].isoformat(),"range_start":args["reference_date"].isoformat(),
                "range_end":(args.get("recheck_at") or args["now"]).date().isoformat(),
                "basis_changed":args["path"].basis_changed,"provenance":"Explicit synthetic scenario facts; no real event-feed authority"}
            cases[f"{cadence}min/{key}"] = {"inputs": {"now": args["now"].isoformat(), "quote": args["quote"].model_dump(mode="json"),
                "market_open": args["market_open"],
                "client_market_open": client_open,
                "path_evidence": "CONTROLLED_SYNTHETIC_EXCHANGE_SESSIONS", "controlling_decision_id": row.decision.canonical.shared_decision_id,
                "assessor_context": context},
                "assessment": result.model_dump(mode="json")}
    return {"evidence_class": "CONTROLLED", "available": True, "source_plan": plan.model_dump(mode="json"), "cases": cases}


def controlled_fixture_payloads(result, transitions):
    """Clone serialized DTOs and replace only read-time controlled quote/evidence."""
    from app.core.audit_hashing import stable_audit_hash
    from app.modules.market_universe.market_universe_schemas import UniverseRowsRead
    from app.modules.stock_details.stock_details_workspace_schemas import StockWorkspaceRead, DisplayMetricsRead
    from app.modules.market_data.market_data_schemas import MarketFreshnessRead
    output = {}
    if not transitions.get("available"):
        return output
    for name, case in transitions["cases"].items():
        generation = "CONTROLLED-" + stable_audit_hash({"source": result["manifest"]["derived_generation"], "case": name, "evidence": case})[:24]
        universe = UniverseRowsRead.model_validate(result["universe"])
        target = next(row for row in universe.rows if row.stock.symbol == "BSRMSTEEL")
        assessment = evaluate_assessment_read(case["assessment"])
        quote = DisplayQuoteRead.model_validate(case["inputs"]["quote"])
        target.entry_applicability = assessment
        target.display_quote = quote
        target.decision = target.decision.model_copy(update={"entry_applicability": assessment})
        now = datetime.fromisoformat(case["inputs"]["now"])
        universe.meta = universe.meta.model_copy(update={"decision_generation_id": generation, "quote_generation_id": generation, "market_sync_id": generation})
        workspace = StockWorkspaceRead.model_validate(result["details"]["BSRMSTEEL"])
        workspace = workspace.model_copy(update={"display_metrics": DisplayMetricsRead.model_validate(quote.model_dump()),
            "market_sync_id": generation, "decision_generation_id": generation, "quote_generation_id": generation,
            "decision_support": workspace.decision_support.model_copy(update={"entry_applicability": assessment,
                "decision_generation_id": generation, "quote_generation_id": generation, "market_sync_id": generation,
                "decision": workspace.decision_support.decision.model_copy(update={"entry_applicability": assessment})})})
        freshness = MarketFreshnessRead(exchange="DSE", trade_date=quote.as_of_trade_date, last_synced_at=now,
            market_sync_id=generation, decision_generation_id=generation, decision_status="CURRENT", data_state="FINALIZED",
            decision_session_date="2026-11-12", next_sync_at=None, snapshot_interval_minutes=int(name.split("min/")[0]),
            market_sync_interval_seconds=int(name.split("min/")[0])*60, dashboard_cache_ttl_seconds=600, expected_delay_minutes=int(name.split("min/")[0]),
            market_open_time="10:00", market_close_time="15:00", market_status="OPEN" if case["inputs"].get("client_market_open") or case["inputs"]["market_open"] else "POST_CLOSE",
            freshness_label="CONTROLLED timing simulation")
        output[name.replace("/", "-")] = {"manifest": {"evidence_class": "CONTROLLED", "case": name, "clock": now.isoformat(),
            "generation": generation, "path": "SYNTHETIC_AUTHENTICATION_AND_EXCHANGE_SESSIONS", "source_plan": result["manifest"]["source_generation"],
            "read_time_assessor": {"contract":"CONTROLLED_ENTRY_FACTS_V1", "stock_id":str(target.stock.id),
                "shared_decision_id":target.decision.canonical.shared_decision_id, "quote":quote.model_dump(mode="json"),
                "plan_hash":stable_audit_hash(target.analysis.trade_plan.model_dump(mode="json")),
                "eligibility_hash":stable_audit_hash(target.eligibility.model_dump(mode="json")),
                "context":case["inputs"]["assessor_context"]}},
            "universe": universe.model_dump(mode="json"), "details": workspace.model_dump(mode="json"), "freshness": freshness.model_dump(mode="json")}
    return output


def reassess_controlled_entry(universe, manifest, *, now):
    """Read-time QA projection over frozen, explicitly controlled assessor facts.

    Only ``now`` and the declared next-open transition advance. Source, receipt,
    publication, plan and path facts never renew when a request arrives.
    """
    from app.modules.stock_details.decision.entry_path_evidence import _time
    from app.core.audit_hashing import stable_audit_hash
    bound=manifest.get("read_time_assessor", {})
    if manifest.get("evidence_class") != "CONTROLLED" or bound.get("contract") != "CONTROLLED_ENTRY_FACTS_V1" or _time(now) is None:
        raise ValueError("A bound controlled assessor context and aware read clock are required")
    row=next(row for row in universe.rows if str(row.stock.id)==bound["stock_id"])
    if universe.meta.decision_generation_id != manifest["generation"] or row.decision.canonical.shared_decision_id != bound["shared_decision_id"]:
        raise ValueError("Controlled assessor owner does not match the immutable fixture")
    if (row.display_quote.model_dump(mode="json") != bound["quote"]
        or stable_audit_hash(row.analysis.trade_plan.model_dump(mode="json")) != bound["plan_hash"]
        or stable_audit_hash(row.eligibility.model_dump(mode="json")) != bound["eligibility_hash"]):
        raise ValueError("Controlled source quote, plan or eligibility changed")
    context=bound["context"]
    path=context["path"]
    facts=EntryPathFacts(sessions=tuple(date.fromisoformat(day) for day in path["sessions"]),
        completed_sessions=frozenset(date.fromisoformat(day) for day in path["completed_sessions"]),
        reliable_lows=tuple((date.fromisoformat(day),low) for day,low in path["reliable_lows"]),
        complete=path["complete"],basis_changed=path["basis_changed"],
        confirmed_on=date.fromisoformat(path["confirmed_on"]) if path.get("confirmed_on") else None,
        ended_sessions=frozenset(date.fromisoformat(day) for day in path["ended_sessions"]) if path.get("ended_sessions") is not None else None)
    kwargs={key:context.get(key) is True for key in ("market_open","coverage_verified","withdrawn","session_settling","price_basis_v2")}
    kwargs.update({key:_time(context.get(key)) for key in ("publication_observed_at","session_open_at","session_close_at","recheck_at")})
    kwargs["finalized_session_date"]=date.fromisoformat(context["finalized_session_date"]) if context.get("finalized_session_date") else None
    basis=context.get("basis_coverage",{})
    kwargs["coverage_verified"]=kwargs["coverage_verified"] and basis.get("status")=="CONTROLLED_PATH_BASIS_FACTS" and basis.get("complete") is True and basis.get("basis_changed")==facts.basis_changed and bool(_time(basis.get("known_at")) and _time(basis["known_at"])<=now and basis.get("range_end","")>=now.date().isoformat())
    next_open=kwargs["recheck_at"]
    next_close=_time(context.get("next_session_close_at"))
    if not kwargs["market_open"] and next_open and now >= next_open:
        kwargs.update(market_open=True,session_open_at=next_open,session_close_at=next_close,recheck_at=None)
        # The fixture attests no further session/path history after this window.
        if next_close is None or now >= next_close:
            kwargs["coverage_verified"]=False
    assessment=evaluate_entry_applicability(decision=row.decision.canonical,plan=row.analysis.trade_plan,eligibility=row.eligibility,
        quote=DisplayQuoteRead.model_validate(bound["quote"]),reference_date=date.fromisoformat(context["reference_date"]),now=now,path=facts,**kwargs)
    return row.stock.id,assessment


def evaluate_assessment_read(payload):
    from app.modules.stock_details.decision.entry_applicability import EntryApplicabilityRead
    return EntryApplicabilityRead.model_validate(payload)
